/**
 * Writes reference/constants.md: every hand-typed (non-formula) value in the
 * sheet, grouped by column into runs of adjacent rows. These are the inputs
 * that must end up in data files.
 *
 * Run: node tools/list-constants.ts
 */
import { writeFileSync } from 'node:fs';
import { colName, loadSheet, type CellValue } from './sheet.ts';

const sheet = loadSheet();
const lines: string[] = [
  '# Constant listing',
  '',
  'Generated by `tools/list-constants.ts`. Every non-formula, non-empty cell.',
  '',
];

const show = (v: CellValue): string =>
  typeof v === 'number' ? String(Math.round(v * 1e6) / 1e6) : JSON.stringify(v);

let total = 0;
for (let col = 0; col < sheet.cols; col++) {
  const name = colName(col);
  const runs: { start: number; values: CellValue[] }[] = [];
  for (let row = 1; row <= sheet.rows; row++) {
    const addr = `${name}${row}`;
    const v = sheet.value(addr);
    if (v === null || v === '' || sheet.formula(addr) !== null) continue;
    total++;
    const last = runs[runs.length - 1];
    if (last && last.start + last.values.length === row) last.values.push(v);
    else runs.push({ start: row, values: [v] });
  }
  if (runs.length === 0) continue;
  lines.push(`## ${name}`, '');
  for (const run of runs) {
    const end = run.start + run.values.length - 1;
    const where = run.values.length === 1 ? `${run.start}` : `${run.start}–${end}`;
    const shown =
      run.values.length <= 12
        ? run.values.map(show).join(', ')
        : `${run.values.slice(0, 6).map(show).join(', ')}, … (${run.values.length} values) …, ${run.values
            .slice(-3)
            .map(show)
            .join(', ')}`;
    lines.push(`- rows ${where}: ${shown}`);
  }
  lines.push('');
}

writeFileSync('reference/constants.md', lines.join('\n'));
console.log(`${total} constant cells`);
